// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {PredictTheBlockHashChallenge} from "../src/PredictTheBlockHashChallenge.sol";

contract InvMutTest is Test {
    PredictTheBlockHashChallenge c;
    function setUp() public { c = new PredictTheBlockHashChallenge{value: 1 ether}(); }

    function testFuzz_property(uint256 startBlock, address actor) public {
        vm.assume(actor != address(0));
        startBlock = bound(startBlock, 1, 10_000_000);
        vm.roll(startBlock);
        vm.deal(actor, 1 ether);
        vm.prank(actor);
        c.lockInGuess{value: 1 ether}(keccak256(abi.encodePacked(actor, startBlock)));

        // settle is possible once the target block (startBlock + 1) has passed
        vm.roll(startBlock + 2);
        vm.prank(actor);
        bool ok;
        try c.settle() { ok = true; } catch { ok = false; }

        assertTrue(ok, "settle must succeed one block after the target block");
    }
}
